                _ = _remove(source, _token);
                _ = Com.Release(source);
                return;
            }
            nint currentToken;
            if (Interop.CoGetContextToken(&currentToken) >= 0 && currentToken == _contextToken)
            {
                _ = _remove(source, _token);
                _ = Com.Release(source);
            }
            else
