                _ = ((delegate* unmanaged<nint, nint, ContextCallData*, Guid*, int, nint, int>)(*(void***)context)[3])(context, (nint)(delegate* unmanaged<ContextCallData*, int>)&RevokeInContext, &data, &iid, 5, 0);
            }
            _ = Com.Release(context);
        }

        [UnmanagedCallersOnly]
        private static int RevokeInContext(ContextCallData* data)
        {
